// @FIGURE_CODE_BEGIN
var svgRoot = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var FW = 700, FH = 580;
svgRoot.viewbox(0, 0, FW, FH);

var OX = 46, OY = 496, SCL = 250;
var SERIF = 'Georgia, "Times New Roman", serif';
var SANS = 'Helvetica, Arial, sans-serif';
var C_ARC = '#28a6de', C_RAY = '#f1626d', C_FILL = '#cfe6f4', C_EDGE = '#74bcdf',
    C_AXIS = '#111111', C_GRAY = '#8b9097';

var gFill = svgRoot.group(), gRay = svgRoot.group(), gArc = svgRoot.group(),
    gAxis = svgRoot.group(), gOv = svgRoot.group(), gLab = svgRoot.group(),
    gRead = svgRoot.group();

var st = { r1: 1.5, r2: 2.0, t1: 1 / 6, t2: 0.25, ov: false };

/* ---------- small helpers ---------- */
function pt(r, th) { return [OX + r * SCL * Math.cos(th), OY - r * SCL * Math.sin(th)]; }
function ptXY(x, y) { return [OX + x * SCL, OY - y * SCL]; }
function fmt(x, n) { return x.toFixed(n); }
function trimNum(x) { return String(parseFloat(x.toFixed(2))); }

function piFrac(t) {
  if (Math.abs(t) < 1e-9) return { kind: 'zero' };
  for (var d = 1; d <= 12; d++) {
    var n = Math.round(t * d);
    if (n >= 1 && Math.abs(t - n / d) < 0.0025) return { kind: 'frac', n: n, d: d };
  }
  return { kind: 'dec', s: t.toFixed(3) };
}
function piText(t) {
  var i = piFrac(t);
  if (i.kind === 'zero') return '0';
  if (i.kind === 'frac') return (i.n > 1 ? i.n + 'π' : 'π') + (i.d > 1 ? '/' + i.d : '');
  return i.s + 'π';
}

function mkText(parent, parts, size) {
  var t = parent.text(function (add) {
    for (var i = 0; i < parts.length; i++) {
      add.tspan(parts[i][0]).font({ style: parts[i][1] ? 'italic' : 'normal' });
    }
  }).font({ family: SERIF, size: size, fill: '#111' });
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 4.5, 'stroke-linejoin': 'round' });
  return t;
}
function placeCenter(el, cx, cy) { var b = el.bbox(); el.translate(cx - (b.x + b.width / 2), cy - (b.y + b.height / 2)); }
function placeRight(el, rx, cy) { var b = el.bbox(); el.translate(rx - (b.x + b.width), cy - (b.y + b.height / 2)); }
function placeLeft(el, lx, cy) { var b = el.bbox(); el.translate(lx - b.x, cy - (b.y + b.height / 2)); }

function arcD(r, a0, a1) {
  var n = 84, d = '', i, p;
  for (i = 0; i <= n; i++) {
    p = pt(r, a0 + (a1 - a0) * i / n);
    d += (i ? 'L' : 'M') + p[0].toFixed(2) + ' ' + p[1].toFixed(2);
  }
  return d;
}
function regionPath(r1, r2, t1, t2) {
  var n = 60, i, p, d;
  p = pt(r1, t1); d = 'M' + p[0] + ' ' + p[1];
  p = pt(r2, t1); d += 'L' + p[0] + ' ' + p[1];
  for (i = 1; i <= n; i++) { p = pt(r2, t1 + (t2 - t1) * i / n); d += 'L' + p[0] + ' ' + p[1]; }
  p = pt(r1, t2); d += 'L' + p[0] + ' ' + p[1];
  for (i = n - 1; i >= 0; i--) { p = pt(r1, t1 + (t2 - t1) * i / n); d += 'L' + p[0] + ' ' + p[1]; }
  return d + 'Z';
}

/* θ = π/6 style label (fraction built from pieces) */
function angleLabelGroup(tval) {
  var F = 22, g = gLab.group();
  var lead = mkText(g, [['θ', true], [' =', false]], F);
  placeLeft(lead, 0, 0);
  var lw = lead.bbox().width;
  var info = piFrac(tval);
  if (info.kind === 'frac' && info.d > 1) {
    var numParts = info.n > 1 ? [[String(info.n), false], ['π', true]] : [['π', true]];
    var num = mkText(g, numParts, F * 0.95);
    var den = mkText(g, [[String(info.d), false]], F * 0.95);
    var fw = Math.max(num.bbox().width, den.bbox().width);
    var fx = lw + 10 + fw / 2;
    placeCenter(num, fx, -14);
    placeCenter(den, fx, 15);
    g.line(fx - fw / 2 - 4, 0, fx + fw / 2 + 4, 0).stroke({ color: '#111', width: 1.8, linecap: 'round' });
  } else if (info.kind === 'frac') {
    var s1 = mkText(g, info.n > 1 ? [[String(info.n), false], ['π', true]] : [['π', true]], F);
    placeLeft(s1, lw + 8, 0);
  } else if (info.kind === 'zero') {
    placeLeft(mkText(g, [['0', false]], F), lw + 8, 0);
  } else {
    placeLeft(mkText(g, [[info.s, false], ['π', true]], F), lw + 8, 0);
  }
  return g;
}

function radiusLabel(r, ang, shiftDown) {
  var p = pt(r, ang);
  var g = mkText(gLab, [['r', true], [' = ' + trimNum(r), false]], 22);
  var b = g.bbox();
  var dy = shiftDown ? 30 : 0;
  if (p[0] - 26 - b.width < 6) placeLeft(g, p[0] + 16, p[1] - 22 + dy);
  else placeRight(g, p[0] - 26, p[1] - 6 + dy);
}

function bracket(A, B, off, parts) {
  var a = ptXY(A[0] + off[0], A[1] + off[1]), b = ptXY(B[0] + off[0], B[1] + off[1]);
  var oa = ptXY(A[0], A[1]), ob = ptXY(B[0], B[1]);
  gOv.line(a[0], a[1], b[0], b[1]).stroke({ color: '#7b8188', width: 1.4 });
  gOv.line(a[0], a[1], oa[0], oa[1]).stroke({ color: '#7b8188', width: 1, dasharray: '2,3' });
  gOv.line(b[0], b[1], ob[0], ob[1]).stroke({ color: '#7b8188', width: 1, dasharray: '2,3' });
  var m = ptXY((A[0] + B[0]) / 2 + off[0] * 2.2, (A[1] + B[1]) / 2 + off[1] * 2.2);
  placeCenter(mkText(gLab, parts, 18), m[0], m[1]);
}

/* ---------- main draw ---------- */
function redraw() {
  var r1 = st.r1, r2 = st.r2, t1 = st.t1 * Math.PI, t2 = st.t2 * Math.PI;
  gFill.clear(); gRay.clear(); gArc.clear(); gAxis.clear(); gOv.clear(); gLab.clear(); gRead.clear();

  var OVA = 0.17;
  var a0 = Math.max(0.035, t1 - OVA), a1 = Math.min(1.52, t2 + OVA);
  var rayR = Math.min(r2 + 0.55, 3.45);

  var mx = Math.max(rayR * Math.cos(t1), r2 * Math.cos(a0), 0.7);
  var my = Math.max(rayR * Math.sin(t2), r2 * Math.sin(a1), 0.5);
  SCL = Math.min(250, (FW - OX - 28) / mx, (OY - 22) / my);

  var dth = t2 - t1, dr = r2 - r1;
  var area = 0.5 * (r2 * r2 - r1 * r1) * dth;

  /* polar axis */
  gAxis.line(OX - 18, OY, FW - 26, OY).stroke({ color: C_AXIS, width: 2.6, linecap: 'round' });

  /* shaded region */
  var reg = gFill.path(regionPath(r1, r2, t1, t2)).fill(C_FILL).stroke({ color: C_EDGE, width: 1.2 });
  reg.css('cursor', 'pointer')
    .on('mousemove', function (e) {
      showTooltip('R:  ' + fmt(r1, 2) + ' ≤ r ≤ ' + fmt(r2, 2) + ',   ' + piText(st.t1) + ' ≤ θ ≤ ' + piText(st.t2) +
        '   ·   area = ' + fmt(area, 4), e);
    })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('The polar rectangle R',
        'R = {(r,θ) : ' + fmt(r1, 2) + ' ≤ r ≤ ' + fmt(r2, 2) + ', ' + piText(st.t1) + ' ≤ θ ≤ ' + piText(st.t2) + '}. ' +
        'Its exact area is ½(r₂² − r₁²)Δθ = ' + fmt(area, 4) + ', which equals r̄·Δr·Δθ with average radius r̄ = (r₁+r₂)/2. ' +
        'That extra factor of r is precisely why the polar area element is dA = r dr dθ.');
    });

  /* dashed red rays of constant θ */
  [[t1, st.t1], [t2, st.t2]].forEach(function (pair) {
    var p = pt(rayR, pair[0]);
    var ln = gRay.line(OX, OY, p[0], p[1]).stroke({ color: C_RAY, width: 2, dasharray: '12,9', linecap: 'butt' });
    ln.css('cursor', 'pointer')
      .on('mousemove', function (e) {
        showTooltip('Constant θ = ' + piText(pair[1]) + ' — a straight radial edge of R, length Δr = ' + fmt(dr, 2), e);
      })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('A ray of constant θ',
          'Holding θ = ' + piText(pair[1]) + ' fixed and letting r vary traces a straight ray from the pole. ' +
          'These two rays are the genuinely straight sides of the polar rectangle; both have the same length Δr = ' + fmt(dr, 2) + '.');
      });
  });

  /* blue arcs of constant r (they overshoot the rays at both ends) */
  [[r1, 'r₁'], [r2, 'r₂']].forEach(function (pair) {
    var r = pair[0];
    var ar = gArc.path(arcD(r, a0, a1)).fill('none')
      .stroke({ color: C_ARC, width: 5, linecap: 'round', linejoin: 'round' });
    ar.css('cursor', 'pointer')
      .on('mousemove', function (e) {
        showTooltip('Constant r = ' + trimNum(r) + ' — a circular arc, not a straight side. Arc length = rΔθ = ' + fmt(r * dth, 3), e);
      })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('An arc of constant r',
          'Holding r = ' + trimNum(r) + ' fixed while θ runs from ' + piText(st.t1) + ' to ' + piText(st.t2) +
          ' sweeps a circular arc of length rΔθ = ' + fmt(r * dth, 3) + '. ' +
          'Because this length is proportional to r, the inner and outer sides of R are never equal: r₁Δθ = ' +
          fmt(r1 * dth, 3) + ' but r₂Δθ = ' + fmt(r2 * dth, 3) + '.');
      });
  });

  /* Cartesian-style comparison rectangle */
  if (st.ov) {
    var ux = Math.cos(t1), uy = Math.sin(t1), vx = -Math.sin(t1), vy = Math.cos(t1);
    var wA = r1 * dth;
    var P0 = [r1 * ux, r1 * uy], P1 = [r2 * ux, r2 * uy];
    var P2 = [P1[0] + wA * vx, P1[1] + wA * vy], P3 = [P0[0] + wA * vx, P0[1] + wA * vy];
    var poly = [P0, P1, P2, P3].map(function (p) { var q = ptXY(p[0], p[1]); return q[0] + ',' + q[1]; }).join(' ');
    var rect = gOv.polygon(poly).fill('none')
      .stroke({ color: C_GRAY, width: 2, dasharray: '7,6', linejoin: 'round' });
    rect.css('cursor', 'pointer')
      .on('mousemove', function (e) {
        showTooltip('True rectangle Δr × r₁Δθ = ' + fmt(dr, 2) + ' × ' + fmt(r1 * dth, 3) +
          ',  area ' + fmt(dr * r1 * dth, 4) + '  (R has area ' + fmt(area, 4) + ')', e);
      })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Rectangle vs. polar rectangle',
          'This straight-sided rectangle has the same Δr = ' + fmt(dr, 2) + ' and the same inner width r₁Δθ = ' +
          fmt(r1 * dth, 3) + ', so it hugs R along the inner arc but falls short of the outer arc, whose length is r₂Δθ = ' +
          fmt(r2 * dth, 3) + '. Its area ' + fmt(dr * r1 * dth, 4) + ' underestimates R\'s area ' + fmt(area, 4) +
          '; as Δr and Δθ shrink the two agree, giving dA = r dr dθ.');
      });
    bracket(P0, P1, [-vx * 0.13, -vy * 0.13], [['Δ', false], ['r', true]]);
    bracket(P0, P3, [-ux * 0.15, -uy * 0.15], [['r', true], ['₁Δ', false], ['θ', true]]);
  }

  /* labels */
  radiusLabel(r2, a1, false);
  radiusLabel(r1, a1, (r2 - r1) * SCL < 42);

  var Rl = mkText(gLab, [['R', true]], 30);
  var pc = pt((r1 + r2) / 2, (t1 + t2) / 2);
  placeCenter(Rl, pc[0], pc[1]);

  var ua = Math.min(t2 + 0.42, 1.53);
  var pu = pt(0.82, ua);
  placeCenter(angleLabelGroup(st.t2), pu[0], pu[1]);

  var la = t1 - 0.30, below = la < 0.13;
  var pl = pt(0.95, Math.max(la, 0.04));
  placeCenter(angleLabelGroup(st.t1), pl[0], pl[1] + (below ? 36 : 0));

  gLab.attr('pointer-events', 'none');

  /* readout */
  var lines = [
    'r₁ = ' + fmt(r1, 2) + '     r₂ = ' + fmt(r2, 2) + '     Δr = ' + fmt(dr, 2),
    'θ₁ = ' + piText(st.t1) + '     θ₂ = ' + piText(st.t2) + '     Δθ = ' + fmt(dth, 3) + ' rad',
    'arc lengths:  r₁Δθ = ' + fmt(r1 * dth, 3) + '     r₂Δθ = ' + fmt(r2 * dth, 3),
    'Area = ½(r₂² − r₁²)Δθ = ' + fmt(area, 4)
  ];
  var bw = 292, bh = 14 + lines.length * 16, bx = FW - 14 - bw, by = OY + 12;
  gRead.rect(bw, bh).move(bx, by).radius(5).fill('#ffffff').opacity(0.94)
    .stroke({ color: '#d5dbe0', width: 1 });
  lines.forEach(function (s, i) {
    gRead.text(s).font({ family: SANS, size: 12, fill: '#2a3138' }).move(bx + 10, by + 5 + i * 16);
  });
  gRead.attr('pointer-events', 'none');
}

/* ---------- controls ---------- */
function setSlider(id, v, dec) {
  var el = document.getElementById(id + 'Input');
  if (el) el.value = v;
  var o = document.getElementById(id + 'Val');
  if (o) o.value = (+v).toFixed(dec);
}
function update_innerRadius(v) {
  st.r1 = v;
  if (st.r2 < st.r1 + 0.1) { st.r2 = Math.min(3, st.r1 + 0.1); setSlider('outerRadius', st.r2, 2); }
  if (st.r1 > st.r2 - 0.1) { st.r1 = st.r2 - 0.1; setSlider('innerRadius', st.r1, 2); }
  redraw();
}
function update_outerRadius(v) {
  st.r2 = v;
  if (st.r1 > st.r2 - 0.1) { st.r1 = Math.max(0.25, st.r2 - 0.1); setSlider('innerRadius', st.r1, 2); }
  if (st.r2 < st.r1 + 0.1) { st.r2 = st.r1 + 0.1; setSlider('outerRadius', st.r2, 2); }
  redraw();
}
function update_startAngle(v) {
  st.t1 = v;
  if (st.t2 < st.t1 + 0.02) { st.t2 = Math.min(0.5, st.t1 + 0.02); setSlider('endAngle', st.t2, 3); }
  if (st.t1 > st.t2 - 0.02) { st.t1 = st.t2 - 0.02; setSlider('startAngle', st.t1, 3); }
  redraw();
}
function update_endAngle(v) {
  st.t2 = v;
  if (st.t1 > st.t2 - 0.02) { st.t1 = Math.max(0, st.t2 - 0.02); setSlider('startAngle', st.t1, 3); }
  if (st.t2 < st.t1 + 0.02) { st.t2 = st.t1 + 0.02; setSlider('endAngle', st.t2, 3); }
  redraw();
}
function toggle_cartesianOverlay(on) { st.ov = !!on; redraw(); }

/* ---------- demo steps ---------- */
var STEPS = [
  { title: 'The polar rectangle R',
    narration: 'R is the set of points whose radius lies between 1.5 and 2 and whose angle lies between π/6 and π/4. Two solid blue arcs and two dashed red rays bound it.',
    state: { r1: 1.5, r2: 2, t1: 1 / 6, t2: 0.25, ov: false } },
  { title: 'Change the radial bounds',
    narration: 'Push the outer arc outward: R thickens radially while the two rays — and therefore the angular extent — stay exactly where they were.',
    state: { r1: 1.5, r2: 2.8, t1: 1 / 6, t2: 0.25, ov: false } },
  { title: 'Shrink Δr toward zero',
    narration: 'Bringing the arcs together turns R into a thin curved strip. In the limit this is the dr in the double integral — the radial slice of the region.',
    state: { r1: 1.85, r2: 2, t1: 1 / 6, t2: 0.25, ov: false } },
  { title: 'Change the angular bounds',
    narration: 'Now hold the radii fixed and swing the rays apart. R sweeps through a wider wedge; its straight radial edges keep the same length, but the arcs get longer.',
    state: { r1: 1.5, r2: 2, t1: 0.05, t2: 0.42, ov: false } },
  { title: 'Compare with a true rectangle',
    narration: 'Overlay a straight-sided rectangle Δr tall and r₁Δθ wide at the inner corner. It hugs R near the inner arc but falls short of the outer arc — the outer side is longer, r₂Δθ.',
    state: { r1: 1.5, r2: 2, t1: 1 / 6, t2: 0.25, ov: true } },
  { title: 'Why dA = r dr dθ',
    narration: 'Shrink Δr and Δθ and the mismatch vanishes: R looks like a rectangle of sides Δr and r Δθ, so its area approaches r Δr Δθ — the polar area element.',
    state: { r1: 1.85, r2: 2, t1: 0.2, t2: 0.25, ov: true } }
];
var curStep = 0;
function applyStep(i) {
  curStep = (i + STEPS.length) % STEPS.length;
  var s = STEPS[curStep];
  st.r1 = s.state.r1; st.r2 = s.state.r2; st.t1 = s.state.t1; st.t2 = s.state.t2; st.ov = s.state.ov;
  setSlider('innerRadius', st.r1, 2);
  setSlider('outerRadius', st.r2, 2);
  setSlider('startAngle', st.t1, 3);
  setSlider('endAngle', st.t2, 3);
  var cb = document.getElementById('cartesianOverlayInput');
  if (cb) cb.checked = st.ov;
  var nar = document.getElementById('demoNarration');
  if (nar) nar.textContent = s.narration;
  var lab = document.getElementById('stepLabel');
  if (lab) lab.textContent = (curStep + 1) + '/' + STEPS.length + ' · ' + s.title;
  redraw();
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

applyStep(0);
window.__markRendered();
